"""Self-contained interactive report; all model-supplied text is rendered as text."""
import json
TEMPLATE=r'''<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>游戏生成器 · Agent 实验室</title>
<style>
:root{--paper:#f4f1e9;--ink:#26362c;--muted:#667066;--rule:#d4dacb;--accent:#526d3a;--wash:#e5ebda;--fail:#a63d2f;--warm:#c17629}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 'Avenir Next','PingFang SC',sans-serif}a{color:var(--accent);text-underline-offset:4px}button,input,select{font:inherit;color:inherit}button{cursor:pointer;background:transparent;border:1px solid var(--rule);padding:7px 13px;border-radius:3px}button:hover{background:var(--wash)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}aside{position:fixed;inset:0 auto 0 0;width:216px;border-right:1px solid var(--rule);padding:34px 23px;display:flex;flex-direction:column}.brand{font-weight:650;font-size:17px}.sub{font-size:12px;color:var(--muted)}nav{margin-top:65px;display:grid;gap:8px}nav button{border:0;text-align:left;padding:12px}nav button.active{background:var(--ink);color:var(--paper)}aside footer{margin-top:auto;font-size:12px;color:var(--muted)}main{margin-left:216px;padding:44px clamp(24px,5vw,80px);max-width:1600px}header{border-bottom:2px solid var(--ink);padding-bottom:25px}h1{font-family:'Iowan Old Style','Songti SC',serif;font-size:clamp(34px,4vw,58px);line-height:1.1;font-weight:500;letter-spacing:-1px;margin:13px 0 19px}h2{font-size:22px;font-weight:600;margin:32px 0 14px}h3{font-size:16px;margin:15px 0 8px}.eyebrow{letter-spacing:2px;text-transform:uppercase;font-size:12px;color:var(--accent)}.status{font-size:12px;padding:3px 8px;background:var(--wash);display:inline-block}.status.fail{color:var(--fail);background:#f0e0d7}.status.pending{color:var(--warm)}.facts{display:flex;gap:24px;flex-wrap:wrap;font-size:13px}.facts strong{font-weight:600}.notice{border-bottom:1px solid var(--rule);padding:17px 0;color:var(--muted);font-size:13px}.overview{display:grid;grid-template-columns:1.2fr 1fr;gap:45px}.chart{width:100%;height:auto;display:block}.table{width:100%;border-collapse:collapse;font-size:13px}.table th{text-align:left;font-weight:500;color:var(--muted);padding:10px 8px;border-bottom:1px solid var(--ink)}.table td{padding:13px 8px;border-bottom:1px solid var(--rule);vertical-align:top}.table tr:hover td{background:var(--wash)}.tools{font-size:12px;color:var(--muted);word-break:break-word}.filter{display:flex;gap:10px;margin:25px 0 14px;flex-wrap:wrap}.filter input{flex:1;min-width:190px;background:transparent;border:1px solid var(--rule);padding:8px 12px}.filter select{background:transparent;padding:8px}.case{border-top:1px solid var(--ink);margin:30px 0;padding:18px 0}.case-head{display:flex;justify-content:space-between;gap:15px;align-items:center}.case-head h2{margin:0;font-size:22px}.metrics{margin:10px 0;color:var(--muted);font-size:13px}.gallery{display:flex;gap:14px;overflow:auto;padding:12px 0}.shot{min-width:128px;text-align:center}.shot img{width:128px;height:128px;image-rendering:pixelated;display:block;background:var(--ink)}.shot span{font-size:11px;color:var(--muted)}details{border-top:1px solid var(--rule);padding:13px 0}summary{cursor:pointer;font-weight:500}pre{font:12px/1.7 'SFMono-Regular','Menlo',monospace;background:#e8e9df;padding:15px;overflow:auto;max-height:410px;white-space:pre-wrap;word-break:break-word}ul{padding-left:20px}.checks{display:grid;grid-template-columns:1fr 1fr;gap:7px 18px;margin:13px 0}.check{font-size:13px}.good{color:var(--accent)}.bad{color:var(--fail)}.links{display:flex;gap:17px;flex-wrap:wrap;font-size:13px}.trace{border-left:2px solid var(--rule);padding-left:16px;margin-top:13px}.trace p{margin:8px 0}.trace small{color:var(--muted);padding-right:12px}audio{width:280px;max-width:100%;height:32px;margin:9px 0}.hidden{display:none!important}.wide-scroll{overflow:auto}.meta-grid{display:grid;grid-template-columns:200px 1fr;gap:8px;font-size:13px}.fingerprint{font-family:'SFMono-Regular','Menlo',monospace;font-size:11px;overflow-wrap:anywhere}footer.bottom{margin-top:60px;border-top:1px solid var(--ink);padding-top:15px;color:var(--muted);font-size:12px}.bar{height:8px;background:var(--accent);margin:4px 0}.empty{padding:25px 0;color:var(--muted)}
@media(max-width:900px){aside{position:static;width:100%;padding:16px 22px;border:0;border-bottom:1px solid var(--rule)}nav{margin-top:12px;display:flex}aside footer{display:none}main{margin:0;padding:26px 22px}.overview{grid-template-columns:1fr;gap:0}.checks{grid-template-columns:1fr}.case-head{align-items:flex-start}.table{min-width:640px}}@media(prefers-reduced-motion:no-preference){main{animation:appear .3s ease-out}@keyframes appear{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}}
</style>
<body><aside><div class="brand">游戏生成器</div><div class="sub">AGENT LAB / 实验记录</div><nav><button class="active" data-page="overview">01　总览</button><button data-page="cases">02　案例与产物</button><button data-page="compare">03　版本对比</button><button data-page="environment">04　环境一致性</button></nav><footer>可复查的规则与产物<br>每个案例独立运行</footer></aside>
<main><header><div class="eyebrow" id="label"></div><h1>让每次迭代<br>都有证据。</h1><div class="facts" id="facts"></div></header><p class="notice" id="notice"></p>
<section id="overview"><div class="overview"><div><h2>运行时间与并行情况</h2><div id="timeline"></div></div><div><h2>需要关注的失败</h2><div id="failures"></div></div></div><h2>案例结果</h2><div class="wide-scroll" id="results"></div></section>
<section id="cases" class="hidden"><div class="filter"><input id="search" aria-label="搜索案例" placeholder="搜索名称、类型或失败原因"><select id="filter" aria-label="筛选状态"><option value="all">全部案例</option><option value="fail">机器检查失败</option><option value="pass">机器检查通过</option></select><button id="download">下载汇总 JSON</button></div><div id="case-list"></div></section>
<section id="compare" class="hidden"><h2>相同案例的版本对比</h2><p class="notice">只比较匹配的案例与重复编号。单次样本不代表稳定提升；提示词之外的代码或模型变化也会影响结果。</p><div id="comparison"></div></section>
<section id="environment" class="hidden"><h2>运行实现与版本指纹</h2><div id="environment-data"></div><h2>证据边界</h2><ul id="limits"></ul></section>
<footer class="bottom">本报告独立于 Agent 的可用工具。按键回放、截图、规则断言和评审均在评测端完成。</footer></main>
<script id="data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);
const text=(tag,value,cls='')=>{const e=document.createElement(tag);e.textContent=value??'';if(cls)e.className=cls;return e};
const num=x=>Number.isFinite(x)?x.toLocaleString('zh-CN',{maximumFractionDigits:1}):'—';
const pass=c=>c.machine_pass?'通过':'失败';
const agentSeconds=c=>c.agent_elapsed_s??(c.result?.elapsed_ms!=null?c.result.elapsed_ms/1000:c.elapsed_s);
function show(name){for(const id of ['overview','cases','compare','environment'])$(id).classList.toggle('hidden',id!==name);for(const b of document.querySelectorAll('nav button'))b.classList.toggle('active',b.dataset.page===name)}
for(const b of document.querySelectorAll('nav button'))b.onclick=()=>show(b.dataset.page);
$('label').textContent=D.label+' / '+D.created_at.slice(0,19).replace('T',' ')+' UTC';
const passed=D.cases.filter(c=>c.machine_pass).length;
for(const [name,value] of [['模型',D.model],['模式',D.mode==='live'?'真实模型':'离线传输夹具'],['机器检查',passed+'/'+D.cases.length],['并行',D.observed_parallelism?D.observed_parallelism+' / '+D.workers:D.workers],['进度',D.complete?'已完成':D.cases.length+'/'+D.total]]){const item=text('span',name+'　');item.append(text('strong',value));$('facts').append(item)}
$('notice').textContent=D.mode==='live'?'本轮运行了真实 Agent 和模型。机器通过率覆盖发布、资源、运行与指定规则；操作手感、视觉与趣味性仍待试玩。':'当前报告使用脚本化 SSE 响应，验证真实原生工具链与并行环境，不代表模型生成质量。使用 --live 开始真实提示词评测。';
if(D.reassessment)$('notice').textContent+=' 本页按修正后的显式判定规则重新评估既有产物，未再次调用模型或重放 VM；原始结果保留。';
function table(parent,headers,rows){const t=document.createElement('table');t.className='table';const h=document.createElement('tr');for(const label of headers)h.append(text('th',label));t.append(h);for(const row of rows){const tr=document.createElement('tr');for(const value of row){const td=document.createElement('td');if(value instanceof Node)td.append(value);else td.textContent=value??'—';tr.append(td)}t.append(tr)}parent.append(t)}
const rows=D.cases.map(c=>{const b=text('button',c.name+' #'+c.replicate);b.onclick=()=>{show('cases');$('search').value=c.id;renderCases()};return [b,text('span',pass(c),'status '+(c.machine_pass?'':'fail')),num(agentSeconds(c))+' / '+num(c.elapsed_s)+'s',num(c.tool_count)+' / '+num(c.tool_errors),num(c.usage?.totalTokens)+(c.usage_complete===false?' *':''),c.review_pending?.length?'需试玩':'—']});
if(D.cases.some(c=>c.usage_complete===false))$('facts').append(text('span','* 失败请求未返回完整用量，token不代表全部消耗','sub'));
table($('results'),['案例','机器检查','Agent / 整轮耗时','工具 / 错误','Token','体验'],rows);
function timeline(){const total=Math.max(1,...D.cases.map(c=>c.end_s||c.elapsed_s||0));const W=680,H=35+D.cases.length*35,ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('role','img');svg.setAttribute('aria-label','各案例起止时间，横条重叠表示并行执行');svg.classList.add('chart');for(let i=0;i<=4;i++){const x=150+i*125,l=document.createElementNS(ns,'line');l.setAttribute('x1',x);l.setAttribute('x2',x);l.setAttribute('y1',22);l.setAttribute('y2',H);l.setAttribute('stroke','#d4dacb');svg.append(l);const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',14);t.setAttribute('fill','#667066');t.setAttribute('font-size',11);t.textContent=num(total*i/4)+'s';svg.append(t)}D.cases.forEach((c,i)=>{const y=35+i*35,t=document.createElementNS(ns,'text');t.setAttribute('x',0);t.setAttribute('y',y+13);t.setAttribute('font-size',11);t.textContent=c.name.slice(0,13)+' #'+c.replicate;svg.append(t);const r=document.createElementNS(ns,'rect');r.setAttribute('x',150+(c.start_s||0)/total*500);r.setAttribute('y',y);r.setAttribute('width',Math.max(2,(c.elapsed_s||0)/total*500));r.setAttribute('height',17);r.setAttribute('fill',c.machine_pass?'#526d3a':'#a63d2f');const title=document.createElementNS(ns,'title');title.textContent=c.name+' '+num(c.elapsed_s)+'s';r.append(title);svg.append(r)});$('timeline').append(svg)}timeline();
const failures=new Map();for(const c of D.cases)for(const check of c.checks||[])if(!check.ok){const old=failures.get(check.name)||[];old.push(c);failures.set(check.name,old)}
if(!failures.size)$('failures').append(text('p','机器检查未发现失败。请继续查看截图、声音和待试玩项；这不是体验已通过。','notice'));
for(const [name,cases] of failures){const p=text('p',name+' · '+cases.length+'例','bad');const b=text('button','查看案例');b.onclick=()=>{show('cases');$('filter').value='fail';renderCases()};p.append(document.createTextNode(' '),b);$('failures').append(p)}
function detail(parent,name,body){const d=document.createElement('details');d.append(text('summary',name));d.append(body);parent.append(d)}
function renderCases(){const query=$('search').value.toLowerCase(),filter=$('filter').value,list=$('case-list');list.replaceChildren();const cases=D.cases.filter(c=>(filter==='all'||(filter==='pass')===!!c.machine_pass)&&JSON.stringify([c.name,c.category,c.id,c.checks]).toLowerCase().includes(query));if(!cases.length){list.append(text('p','没有匹配案例。','empty'));return}for(const c of cases){const box=text('article','','case'),head=text('div','','case-head');head.append(text('h2',c.name+' #'+c.replicate),text('span',pass(c),'status '+(c.machine_pass?'':'fail')));box.append(head,text('p',`Agent ${num(agentSeconds(c))}s / 整轮 ${num(c.elapsed_s)}s · 首次流式输出 ${num(c.first_output_ms)}ms · ${num(c.usage?.totalTokens)} ${c.usage_complete===false?'已返回 token（不完整）':'token'} · ${num(c.tool_count)} 工具调用 · ${num(c.tool_errors)} 工具错误`,'metrics'));
if(c.result?.error)box.append(text('pre',c.result.error,'bad'));
const links=text('div','','links');for(const [name,path] of [['卡带','game.p8'],['源码','game.lua'],['工具轨迹','trace.json'],['项目历史','project.json'],['真实提示词','prompt-1.txt']]){if(c.artifacts&&!c.artifacts.includes(path))continue;const a=text('a',name),embedded=D.embedded_files?.[c.slug+'/'+path];a.href=embedded||'cases/'+encodeURIComponent(c.slug)+'/'+path;if(embedded)a.download=c.slug+'-'+path;links.append(a)}box.append(links);
const gallery=text('div','','gallery');for(const cap of c.runtime?.captures||[]){if(!cap.image?.startsWith('data:image/png;base64,'))continue;const shot=text('div','','shot'),img=document.createElement('img');img.src=cap.image;img.alt=c.name+' '+cap.name;shot.append(img,text('span',cap.name));gallery.append(shot)}box.append(gallery);
if(c.runtime?.captures?.length){const audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.src=D.embedded_files?.[c.slug+'/replay/audio.wav']||'cases/'+encodeURIComponent(c.slug)+'/replay/audio.wav';box.append(audio)}
const checks=text('div','','checks');for(const check of c.checks||[]){const item=text('div',(check.ok?'✓ ':'× ')+check.name,'check '+(check.ok?'good':'bad'));item.title=check.reason||'';checks.append(item)}box.append(checks,text('p','待试玩：'+(c.review_pending||[]).join(' / '),'notice'));
if(c.delivery_warnings?.length)detail(box,'交付警告 · 待核实',text('pre',c.delivery_warnings.join('\n')));
const req=text('div','');for(const p of c.requirements||[])req.append(text('p',p));detail(box,'输入需求与判据',req);
const trace=text('div','','trace');for(const e of c.result?.events||[]){if(!['tool_execution_start','tool_execution_end','retry','error'].includes(e.type))continue;const p=text('p','');p.append(text('small',num(e.ms/1000)+'s'),text('span',e.tool||e.type,e.error?'bad':''));trace.append(p);if(e.type==='tool_execution_start'&&e.args)detail(trace,'参数',text('pre',JSON.stringify(e.args,null,2)));if(e.type==='error'&&e.message)trace.append(text('pre',e.message,'bad'));if(e.error)trace.append(text('pre',JSON.stringify(e.result,null,2)))}detail(box,'Agent执行轨迹',trace);
const runtime=text('pre',JSON.stringify(c.runtime?.events||[],null,2)+(c.runtime?.error?'\n'+c.runtime.error:''));detail(box,'真实fake-08运行与断言',runtime);
if(c.service_metrics?.httpReceivedBytes!=null){const metrics=text('div','');table(metrics,['原生网络指标','数值'],[['累计接收',num(c.service_metrics.httpReceivedBytes/1048576)+' MiB'],['已交付并回收',num(c.service_metrics.httpReclaimedBytes/1048576)+' MiB'],['单请求缓冲分配峰值',num(c.service_metrics.httpPeakBufferBytes/1024)+' KiB'],['单次 SSE 交付峰值',num(c.service_metrics.httpMaxProgressBytes/1024)+' KiB']]);detail(box,'流式响应缓冲',metrics)}
if(c.review_skip_reason)box.append(text('p','评审跳过：'+c.review_skip_reason,'notice'));
if(c.rubric_review){const review=text('div','');if(c.rubric_review.valid_for_generation===false)review.append(text('p','本次评审针对未改变的初始脚手架；不能评价本轮生成质量。','bad'));review.append(text('p','模型代码评审 · 待核实。引用仅校验行号范围，意见可能有误；核实后再调整提示词。'));if(c.rubric_review.ok){table(review,['指标','0–4','理由与行号'],c.rubric_review.criteria.map(x=>[x.name,x.score,x.reason+' '+(x.lines?.length?'L'+x.lines.join('–'):'')]));for(const tip of c.rubric_review.suggestions||[])review.append(text('p',tip))}else review.append(text('p',c.rubric_review.error,'bad'));detail(box,'可选模型评审',review)}list.append(box)}}
$('search').oninput=renderCases;$('filter').onchange=renderCases;renderCases();
$('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));a.download='summary.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
if(!D.baseline)$('comparison').append(text('p','下一轮添加 --compare 上一轮/summary.json，即可生成逐案例对照。比较时保持模型、案例和重复次数相同。','empty'));
else{table($('comparison'),['案例',D.baseline.label,D.label,'Agent耗时变化','Token变化','代码评审'],D.cases.map(c=>{const b=D.baseline.cases.find(x=>x.id===c.id&&x.replicate===c.replicate);return [c.name+' #'+c.replicate,b?pass(b):'无匹配',pass(c),b?num(agentSeconds(c)-agentSeconds(b))+'s':'—',b?(c.usage_complete===false||b.usage_complete===false?'不完整，不比较':num((c.usage?.totalTokens||0)-(b.usage?.totalTokens||0))):'—',c.rubric_review?.ok?c.rubric_review.criteria.map(x=>x.score).join('/'):'未启用']}))}
const meta=text('div','','meta-grid');for(const [name,value] of [['QuickJS',D.build.quickjs_version+' / '+D.build.quickjs_stack_kib+' KiB stack'],['Pi',D.build.pi_version],['fake-08',D.build.fake08_revision],['z8lua',D.build.z8lua_revision],['源码指纹',D.build.source.sha256],['Skill包',D.build.skill_bundle_sha256],['ARM一致性',D.device_parity?D.device_parity.ok?'通过 · 相同工具路径与卡带字节':'失败 · 查看下方证据':'本轮未执行；可添加 --parity-ssh nextui-brick'],['Agent范围','原有六个工具；评测没有新增截图、执行Lua或shell工具']]){meta.append(text('div',name,'sub'),text('div',value,'fingerprint'))}$('environment-data').append(meta);if(D.device_parity)detail($('environment-data'),'ARM对照结果',text('pre',JSON.stringify(D.device_parity,null,2)));for(const x of D.limitations)$('limits').append(text('li',x));
if(D.reassessment)detail($('environment-data'),'重新评估记录 · 保留原始产物',text('pre',JSON.stringify(D.reassessment,null,2)));
</script></body></html>'''
def render_report(data):
 payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
 return TEMPLATE.replace('__DATA__',payload)
